<?php

declare(strict_types=1);

namespace DealDist\Http\Controller;

use Psr\Http\Message\ResponseInterface;
use Psr\Http\Message\ServerRequestInterface;

/**
 * Публичные страницы политики конфиденциальности (для amoМаркета).
 *   GET /privacy      — RU
 *   GET /privacy/en   — EN
 * HTML встроен base64, чтобы не зависеть от файловой раскладки.
 */
final class PrivacyController
{
    private const RU_B64 = "";
    /** Kommo listing: no amoCRM mentions, "leads" terminology, generic payment provider. */
    private const KOMMO_B64 = "";
    private const EN_B64 = "";

    public function ru(ServerRequestInterface $request, ResponseInterface $response): ResponseInterface
    {
        return $this->html($response, (string) base64_decode(self::RU_B64));
    }

    public function en(ServerRequestInterface $request, ResponseInterface $response): ResponseInterface
    {
        return $this->html($response, (string) base64_decode(self::EN_B64));
    }

    public function kommo(ServerRequestInterface $request, ResponseInterface $response): ResponseInterface
    {
        return $this->html($response, (string) base64_decode(self::KOMMO_B64));
    }

    private function html(ResponseInterface $response, string $body): ResponseInterface
    {
        $response->getBody()->write($body);
        return $response->withStatus(200)->withHeader('Content-Type', 'text/html; charset=utf-8');
    }
}
